ALTER TABLE buses ADD COLUMN IF NOT EXISTS route_id UUID REFERENCES routes(id) ON DELETE SET NULL;

ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  code = EXCLUDED.code,
  origin = EXCLUDED.origin,
  destination = EXCLUDED.destination,
  distance_km = EXCLUDED.distance_km,
  estimated_minutes = EXCLUDED.estimated_minutes;

DELETE FROM buses WHERE id NOT IN ('11111111-0003-0001-0000-000000000001', '11111111-0003-0001-0000-000000000002', '11111111-0003-0001-0000-000000000003', '11111111-0003-0001-0000-000000000004', '11111111-0003-0001-0000-000000000005', '22222222-0003-0001-0000-000000000001', '22222222-0003-0001-0000-000000000002', '22222222-0003-0001-0000-000000000003', '22222222-0003-0001-0000-000000000004', '22222222-0003-0001-0000-000000000005', '33333333-0003-0001-0000-000000000001', '33333333-0003-0001-0000-000000000002', '33333333-0003-0001-0000-000000000003', '33333333-0003-0001-0000-000000000004', '33333333-0003-0001-0000-000000000005', '44444444-0003-0001-0000-000000000001', '44444444-0003-0001-0000-000000000002', '44444444-0003-0001-0000-000000000003', '44444444-0003-0001-0000-000000000004', '44444444-0003-0001-0000-000000000005', '55555555-0003-0001-0000-000000000001', '55555555-0003-0001-0000-000000000002', '55555555-0003-0001-0000-000000000003', '55555555-0003-0001-0000-000000000004', '55555555-0003-0001-0000-000000000005', '66666666-0003-0001-0000-000000000001', '66666666-0003-0001-0000-000000000002', '66666666-0003-0001-0000-000000000003', '66666666-0003-0001-0000-000000000004', '66666666-0003-0001-0000-000000000005', '77777777-0003-0001-0000-000000000001', '77777777-0003-0001-0000-000000000002', '77777777-0003-0001-0000-000000000003', '77777777-0003-0001-0000-000000000004', '77777777-0003-0001-0000-000000000005');

DELETE FROM routes WHERE id NOT IN ('11111111-0002-0001-0000-000000000001', '11111111-0002-0001-0000-000000000002', '11111111-0002-0001-0000-000000000003', '11111111-0002-0001-0000-000000000004', '11111111-0002-0001-0000-000000000005', '22222222-0002-0001-0000-000000000001', '22222222-0002-0001-0000-000000000002', '22222222-0002-0001-0000-000000000003', '22222222-0002-0001-0000-000000000004', '22222222-0002-0001-0000-000000000005', '33333333-0002-0001-0000-000000000001', '33333333-0002-0001-0000-000000000002', '33333333-0002-0001-0000-000000000003', '33333333-0002-0001-0000-000000000004', '33333333-0002-0001-0000-000000000005', '44444444-0002-0001-0000-000000000001', '44444444-0002-0001-0000-000000000002', '44444444-0002-0001-0000-000000000003', '44444444-0002-0001-0000-000000000004', '44444444-0002-0001-0000-000000000005', '55555555-0002-0001-0000-000000000001', '55555555-0002-0001-0000-000000000002', '55555555-0002-0001-0000-000000000003', '55555555-0002-0001-0000-000000000004', '55555555-0002-0001-0000-000000000005', '66666666-0002-0001-0000-000000000001', '66666666-0002-0001-0000-000000000002', '66666666-0002-0001-0000-000000000003', '66666666-0002-0001-0000-000000000004', '66666666-0002-0001-0000-000000000005', '77777777-0002-0001-0000-000000000001', '77777777-0002-0001-0000-000000000002', '77777777-0002-0001-0000-000000000003', '77777777-0002-0001-0000-000000000004', '77777777-0002-0001-0000-000000000005');

ON CONFLICT (id) DO UPDATE SET
  tenant_id = EXCLUDED.tenant_id,
  route_id = EXCLUDED.route_id,
  fleet_code = EXCLUDED.fleet_code,
  plate_number = EXCLUDED.plate_number,
  model = EXCLUDED.model,
  capacity = EXCLUDED.capacity,
  status = EXCLUDED.status,
  trip_status = EXCLUDED.trip_status,
  current_stop_sequence = EXCLUDED.current_stop_sequence,
  progress_pct = EXCLUDED.progress_pct,
  route_variant = EXCLUDED.route_variant,
  traffic_level = EXCLUDED.traffic_level,
  delay_minutes = EXCLUDED.delay_minutes,
  dwell_seconds = EXCLUDED.dwell_seconds,
  segment_progress = EXCLUDED.segment_progress;

DELETE FROM route_stops;


SELECT 
  ('00000000-0004-' || substr(b.id::text, 1, 4) || '-' || substr(b.id::text, 5, 4) || '-' || substr(b.id::text, 25, 12))::uuid,
  b.tenant_id,
  b.id,
  b.route_id,
  NOW() + ((substr(b.id::text, 36, 1)::int * 5) * INTERVAL '1 minute'),
  'SCHEDULED'
FROM buses b
WHERE b.route_id IS NOT NULL
ON CONFLICT (id) DO UPDATE SET
  bus_id = EXCLUDED.bus_id,
  route_id = EXCLUDED.route_id,
  status = EXCLUDED.status;

DELETE FROM bus_telemetry;

SELECT 
  b.tenant_id,
  b.id,
  b.route_id,
  NOW(),
  s.latitude,
  s.longitude,
  36.5,
  90.0,
  22,
  s.location
FROM buses b
JOIN route_stops rs ON rs.route_id = b.route_id AND rs.stop_sequence = b.current_stop_sequence
JOIN stops s ON s.id = rs.stop_id;
